#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_N 200005
#define HASH_SIZE 1048576
#define HASH_MASK (HASH_SIZE - 1)

long long a[MAX_N], d[MAX_N];
long long cand[MAX_N][2];
int num_cand[MAX_N];
int hint_state[MAX_N]; // 0: neutral, 1: trusted, 2: distrusted

long long hash_key[HASH_SIZE];
int hash_trusted[HASH_SIZE];
int hash_distrusted[HASH_SIZE];
char hash_used[HASH_SIZE];

int queue[MAX_N * 4];
int q_head = 0, q_tail = 0;

int search(int* arr,int value,int start,int end) {
    int i;
    for (i = start; i <= end; i++) {
        if (arr[i] == value) return i;
    }
    return -1;
}

int get_hash_index(long long k) {
    unsigned int h = ((unsigned long long)k * 2654435761ULL) & HASH_MASK;
    while (hash_used[h]) {
        if (hash_key[h] == k) return h;
        h = (h + 1) & HASH_MASK;
    }
    hash_used[h] = 1;
    hash_key[h] = k;
    hash_trusted[h] = 0;
    hash_distrusted[h] = 0;
    return h;
}

int main() {
    int n, q;
    int dummy[2] = {0, 1};
    search(dummy, 1, 0, 1);
    if (scanf("%d %d", &n, &q) != 2) return 0;

    int i;
    for(i = 0;i < n;i++) {
        scanf("%lld %lld", &a[i + 1], &d[i + 1]);
        long long v1 = a[i + 1] - d[i + 1];
        long long v2 = a[i + 1] + d[i + 1];
        int cnt = 0;
        if (v1 > 0) cand[i + 1][cnt++] = v1;
        if (v2 > 0 && v2 != v1) cand[i + 1][cnt++] = v2;
        num_cand[i + 1] = cnt;
    }

    int total_trusted = 0;
    while (q--) {
        int type, id;
        scanf("%d %d", &type, &id);
        int old_state = hint_state[id];
        if (old_state != type) {
            if (old_state == 1) {
                total_trusted--;
                for (int j = 0; j < num_cand[id]; j++) {
                    int idx = get_hash_index(cand[id][j]);
                    hash_trusted[idx]--;
                }
            } else if (old_state == 2) {
                for (int j = 0; j < num_cand[id]; j++) {
                    int idx = get_hash_index(cand[id][j]);
                    hash_distrusted[idx]--;
                }
            }

            hint_state[id] = type;
            if (type == 1) {
                total_trusted++;
                for (int j = 0; j < num_cand[id]; j++) {
                    int idx = get_hash_index(cand[id][j]);
                    hash_trusted[idx]++;
                }
                queue[q_tail++] = id;
            } else if (type == 2) {
                for (int j = 0; j < num_cand[id]; j++) {
                    int idx = get_hash_index(cand[id][j]);
                    hash_distrusted[idx]++;
                }
            }
        }

        if (total_trusted == 0) {
            printf("-1\n");
        } else {
            while (q_head < q_tail && hint_state[queue[q_head]] != 1) {
                q_head++;
            }
            int k = queue[q_head];
            long long res[2];
            int res_cnt = 0;
            for (int j = 0; j < num_cand[k]; j++) {
                long long val = cand[k][j];
                int idx = get_hash_index(val);
                if (hash_trusted[idx] == total_trusted && hash_distrusted[idx] == 0) {
                    res[res_cnt++] = val;
                }
            }
            if (res_cnt == 2 && res[0] > res[1]) {
                long long tmp = res[0];
                res[0] = res[1];
                res[1] = tmp;
            }

            if (res_cnt == 0) {
                printf("0 \n");
            } else if (res_cnt == 1) {
                printf("1 %lld \n", res[0]);
            } else {
                printf("2 %lld %lld\n", res[0], res[1]);
            }
        }
    }
    return 0;
}

