int valid(int rem) {
    for (int j = 0; j < 26; j++) if (cnt[j] > rem) return 0;
    return 1;
}

int main() {
    if (scanf("%s", s) != 1) return 0;
    int n = strlen(s), i, last = -1;
    for(i=0;i<n;i++) cnt[s[i] - 'A']++;
    if (!valid((n + 1) / 2)) { puts("-1"); return 0; }
    for (i = 0; i < n; i++) {
        int rem = (n - i) / 2;
        for (int c = 0; c < 26; c++) {
            if (c == last) continue;
            if (!cnt[c]) continue;
            cnt[c]--;
            if (valid(rem)) { putchar('A' + c); last = c; break; }
            cnt[c]++;
        }
    }
    putchar('\n');
    return 0;
}

